pipeline {
  agent none

  stages {
stage('Release') {
  agent { label 'linux && release' }
  steps {
    checkout scm
    sh 'npm ci'
    sh 'npm run lint'
    sh 'npm test'
    sh 'npm run build'
    sh './scripts/deploy.sh staging'
  }

}
  }
}

